CREATE TABLE oauth_states(state TEXT PRIMARY KEY,owner_id TEXT NOT NULL,connection_id TEXT NOT NULL REFERENCES mcp_connections(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE tool_invocations(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,run_id TEXT NOT NULL REFERENCES runs(id),connection_id TEXT NOT NULL REFERENCES mcp_connections(id),agent_id TEXT NOT NULL REFERENCES agents(id),call_id TEXT NOT NULL,tool TEXT NOT NULL,args TEXT NOT NULL,state TEXT NOT NULL,approval_id TEXT REFERENCES approvals(id),result TEXT,artifact_id TEXT REFERENCES artifacts(id),created_at INTEGER NOT NULL,UNIQUE(run_id,call_id));
CREATE TABLE agent_checkpoints(run_id TEXT PRIMARY KEY REFERENCES runs(id) ON DELETE CASCADE,message_id TEXT NOT NULL REFERENCES messages(id),artifact_id TEXT NOT NULL REFERENCES artifacts(id),round INTEGER NOT NULL DEFAULT 0,history TEXT NOT NULL,pending TEXT NOT NULL DEFAULT '[]',output TEXT NOT NULL DEFAULT '',stage TEXT NOT NULL DEFAULT 'model');
INSERT INTO schema_version VALUES(5,unixepoch()*1000);
